CA;AACA,aAAa;AACb;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA,mBAAmB;AACnB;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,+BAA+B;AAC/B;AACA;AACA;AACA;AACA;AACA,mBAAmB;AACnB;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yCAAyC;AACzC;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2CAA2C;AAC3C;AACA;AACA;AACA;AACA,mCAAmC;AACnC;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2BAA2B;AAC3B;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA,WAAW;AACX;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;ACjLA;AAAA;AAAA;AAAA;AAA+F;AAC3B;AACL;;;AAG/D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,sFAAM;AACR,EAAE,2FAAM;AACR,EAAE,oGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAwM,CAAgB,oPAAG,EAAC,C;;;;;;;;;;;;ACA5N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAkG;AAC3B;AACL;;;AAGlE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,yFAAM;AACR,EAAE,8FAAM;AACR,EAAE,uGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA2M,CAAgB,uPAAG,EAAC,C;;;;;;;;;;;;ACA/N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAA+F;AAC3B;AACL;;;AAG/D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,sFAAM;AACR,EAAE,2FAAM;AACR,EAAE,oGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAwM,CAAgB,oPAAG,EAAC,C;;;;;;;;;;;;ACA5N;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-7.js","sourcesContent":["<template>\n    <div v-if=\"hasLabel || isBundle || isSet\" class=\"special-tags p-2\">\n        \n        <span v-if=\"hasLabel\" class=\"badge\" :class=\"tagClass\">\n            {{ label }}\n        </span>\n\n        <span v-else-if=\"isBundle\" :class=\"tagClasses.itemBundle\">\n            {{ $translate(\"Ceres::Template.itemBundle\") }}\n        </span>\n\n        <span v-else-if=\"isSet\" :class=\"tagClasses.itemSet\">\n            {{ $translate(\"Ceres::Template.itemSet\") }}\n        </span>\n\n    </div>\n</template>\n\n<script>\nimport { isNullOrUndefined, isDefined } from \"../../helper/utils\";\n\nexport default {\n\n    name: \"item-store-special\",\n\n    props: [\n        \"storeSpecial\",\n        \"recommendedRetailPrice\",\n        \"variationRetailPrice\",\n        \"specialOfferPrice\",\n        \"decimalCount\",\n        \"bundleType\",\n        \"itemType\"\n    ],\n\n    data()\n    {\n        return {\n            tagClass: \"\",\n            label: \"\",\n            tagClasses:\n            {\n                1: \"badge-offer badge-danger\",\n                2: \"badge-new badge-primary\",\n                3: \"badge-top badge-success\",\n                default: \"badge-success\",\n                itemBundle: \"badge badge-bundle bg-info\",\n                itemSet: \"badge badge-dark\"\n            },\n            labels:\n            {\n                1: this.$translate(\"Ceres::Template.storeSpecialOffer\"),\n                2: this.$translate(\"Ceres::Template.storeSpecialNew\"),\n                3: this.$translate(\"Ceres::Template.storeSpecialTop\")\n            }\n        };\n    },\n\n    computed:\n    {\n        hasLabel() {\n            return this.label && this.label !== \"\";\n        },\n\n        isBundle() {\n            return this.bundleType === \"bundle\";\n        },\n\n        isSet() {\n            return this.itemType === \"set\";\n        }\n    },\n\n    created()\n    {\n        this.initializeStoreSpecial();\n    },\n\n    methods:\n    {\n        initializeStoreSpecial()\n        {\n            if (!isNullOrUndefined(this.storeSpecial))\n            {\n                this.tagClass = this.tagClasses[this.storeSpecial.id] || this.tagClasses.default;\n            }\n            else\n            {\n                this.tagClass = this.tagClasses.default;\n            }\n\n            this.label = this.getLabel();\n        },\n\n        getLabel()\n        {\n            if (!isNullOrUndefined(this.storeSpecial) && this.storeSpecial.id === 1 && !isNullOrUndefined(this.recommendedRetailPrice))\n            {\n                return this.getPercentageSale();\n            }\n\n            if (isNullOrUndefined(this.storeSpecial))\n            {\n                return \"\";\n            }\n\n            return this.labels[this.storeSpecial.id] || this.storeSpecial.names.name;\n        },\n\n        getPercentageSale()\n        {\n            let percent;\n\n            if (isDefined(this.specialOfferPrice))\n            {\n                percent = (1 - this.specialOfferPrice.unitPrice.value / this.variationRetailPrice.unitPrice.value ) * -100;\n            }\n            else\n            {\n                percent = (1 - this.variationRetailPrice.unitPrice.value / this.recommendedRetailPrice.unitPrice.value ) * -100;\n            }\n\n            if (percent < 0)\n            {\n                return percent.toFixed(this.decimalCount).replace(\".\", App.decimalSeparator) + \"%\";\n            }\n\n            return \"\";\n        }\n    },\n\n    watch:\n    {\n        storeSpecial()\n        {\n            this.initializeStoreSpecial();\n        }\n    }\n}\n</script>\n","<template>\n    <div class=\"live-shopping-details\">\n        <div class=\"h3 live-shopping-item-name\">\n            <a :href=\"liveShoppingData.item | itemURL\">\n                <div class=\"two-lines-of-text\">\n                    {{ (liveShoppingData.item.texts.name1.match(/[^\\ - ]+ -/) || ['']).pop() }} \n                    {{ liveShoppingData.item.texts.name2 }}\n                </div>\n                <span class=\"live-shopping-item-name-condition two-lines-of-text\">{{ liveShoppingData.item.texts.name3 }}</span>\n            </a>\n        </div>\n        <div class=\"live-shopping-prices\" v-if=\"hasStarted\">\n            <div class=\"live-shopping-prices-inner\">\n                <div class=\"live-shopping-prices-container\">\n                    <span v-if=\"displaySettings.showCrossPrice && prices.rrp && prices.rrp.unitPrice.value > 0\">\n                        <span v-if=\"liveShoppingData.item.prices.default.unitPrice.value > liveShoppingData.item.prices.rrp.unitPrice.value\">\n                            statt <del>{{ liveShoppingData.item.prices.default.unitPrice.formatted }}</del>\n                        </span>\n                        <span v-else>\n                            statt <del>{{ liveShoppingData.item.prices.rrp.unitPrice.formatted }}</del>\n                        </span>\n                    </span>\n\n                    <span v-if=\"displaySettings.showCrossPrice && prices.rrp && prices.rrp.unitPrice.value === 0\">\n                        <span>&nbsp;</span>\n                    </span>\n\n                    <div class=\"live-shopping-price\">\n                        <strong><span class=\"d-none d-lg-inline\">heute </span>nur {{ prices.price.unitPrice.formatted }}</strong>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"live-shopping-prices-additional-info\">\n                <div v-if=\"!(liveShoppingData.item.unit.unitOfMeasurement === 'C62' && liveShoppingData.item.unit.content === 1)\">\n                    <span>{{ liveShoppingData.item.unit.content }}</span>\n                    <span>{{ liveShoppingData.item.unit.names.name }}</span>\n                    <span v-if=\"liveShoppingData.item.variation.mayShowUnitPrice\">| {{ prices.price.basePrice }}</span>\n                </div>\n\n                <template v-if=\"showNetPrices\">{{ $translate(\"Ceres::Template.itemExclVAT\") }}</template><template v-else>{{ $translate(\"Ceres::Template.itemInclVAT\") }}</template> {{ $translate(\"Ceres::Template.itemExclusive\") }}\n                <a v-if=\"$ceres.config.global.shippingCostsCategoryId > 0\" href=\"https://www.konsolenkost.de/versand\" :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                <a v-else :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n            </div>\n        </div>\n        <div v-if=\"!hasClosed\">\n            <a class=\"btn btn-primary d-block d-lg-inline-block my-lg-3\" :href=\"liveShoppingData.item | itemURL\">\n                Will ich haben <span class=\"d-none d-lg-inline\">&gt;</span>\n            </a>\n        </div>\n\n        <div v-else>\n            <a class=\"btn btn-primary btn-danger text-white d-block d-lg-inline-block my-lg-3\">\n               AUSVERKAUFT* <span class=\"d-none d-lg-inline\"></span>\n            </a>\n        </div>\n\n        <slot name=\"after-item-name\"></slot>\n\n        <div class=\"live-shopping-countdown\" v-if=\"displaySettings.showTimer || displaySettings.showStock\">\n\n            <template v-if=\"hasStarted && !hasClosed\">\n                <div class=\"live-shopping-progress\" v-if=\"displaySettings.showStock\">\n                    <div class=\"progress\" v-if=\"displaySettings.showStockProgress\">\n                        <div :class=\"'progress-' + Math.round(quantitySoldPercentage / 10) * 10\" class=\"progress-bar\" role=\"progressbar\" :style=\"'width:' + quantitySoldPercentage + '%'\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\" v-if=\"liveShoppingData.liveShopping.quantitySold < liveShoppingData.liveShopping.quantityMax\"></div>\n                        <div class=\"progress-bar-done\" role=\"progressbar\" style=\"width: 100%\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\" v-else></div>\n                    </div>\n                    <div class=\"live-shopping-progress-heading\">\n                        <span>{{ $translate(\"Ceres::Template.liveShoppingRemainingStock\", {\"quantitySoldPercentage\": quantitySoldPercentage }) }}</span>\n                    </div>\n                </div>\n            </template>\n\n            <template v-if=\"hasClosed\">\n                <div class=\"live-shopping-progress\" v-if=\"displaySettings.showStock\">\n                    <div class=\"progress\" v-if=\"displaySettings.showStockProgress\">\n                        <div class=\"progress-10\" role=\"progressbar\" style=\"width: 100%\" aria-valuemin=\"0\" aria-valuemax=\"100\" v-if=\"liveShoppingData.liveShopping.quantitySold < liveShoppingData.liveShopping.quantityMax\"></div>\n                        <div class=\"progress-bar-done\" role=\"progressbar\" style=\"width: 100%\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\" v-else></div>\n                    </div>\n                    <div class=\"live-shopping-progress-heading\">\n                        <span>*Aktionsbestand ausverkauft</span>\n                    </div>\n                </div>\n            </template>\n\n        </div>\n\n        <div class=\"thumb-content\" v-else>\n            <div>\n                <div class=\"prices\">\n                    <div class=\"price-view-port\">\n                        <del class=\"crossprice\" v-if=\"displaySettings.showCrossPrice && prices.rrp.price.value > 0\">\n                            {{ prices.rrp.price.formatted | itemCrossPrice  }}\n                        </del>\n                    </div>\n\n                    <div class=\"price\">\n                        {{ prices.price.price.formatted }} *\n                    </div>\n                </div>\n\n                <div class=\"category-unit-price small\" v-if=\"!(liveShoppingData.item.unit.unitOfMeasurement === 'C62' && liveShoppingData.item.unit.content === 1)\">\n                    <span>{{ liveShoppingData.item.unit.content }}</span>\n                    <span>{{ liveShoppingData.item.unit.names.name }}</span>\n                    <span v-if=\"liveShoppingData.item.variation.mayShowUnitPrice\">| {{ prices.price.basePrice }}</span>\n                </div>\n\n                <span class=\"vat small text-muted\">\n                    <template v-if=\"showNetPrices\">{{ $translate(\"Ceres::Template.itemExclVAT\") }}</template><template v-else>{{ $translate(\"Ceres::Template.itemInclVAT\") }}</template> {{ $translate(\"Ceres::Template.itemExclusive\") }}\n                    <a v-if=\"$ceres.config.global.shippingCostsCategoryId > 0\" href=\"https://www.konsolenkost.de/versand\" :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                    <a v-else :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                </span>\n            </div>\n        </div>\n\n    </div>\n</template>\n\n<script>\nimport dayjs from \"dayjs\";\n\nexport default {\n    props:\n    {\n        liveShoppingData:\n        {\n            type: Object,\n            required: true\n        },\n\n        displaySettings:\n        {\n            type: Object,\n            default: () =>\n            {\n                return {\n                    showCrossPrice: true,\n                    showStock: true,\n                    showStockProgress: true,\n                    showTimer: true,\n                    showTimerProgress: true\n                };\n            }\n        },\n\n        prices:\n        {\n            type: Object,\n            required: true\n        },\n\n        isActiveByStock:\n        {\n            type: Boolean\n        },\n\n        showNetPrices:\n        {\n            type: Boolean\n        }\n    },\n\n    data()\n    {\n        return {\n            currentInterval: null,\n            duration: null,\n            hasClosed: null,\n            hasStarted: null,\n            itemPriceRebatePercentage: 0,\n            itemQuantityRemaining: 0,\n            momentBegin: null,\n            momentEnd: null,\n            quantitySoldPercentage: 0,\n            timePercentage: 0\n        };\n    },\n\n    computed:\n    {\n        oldPriceBefore()\n        {\n            return this.$translate('Ceres::Template.liveShoppingBefore', {'price': '<del>' + this.prices.rrp.unitPrice.formatted + '</del>'})\n        },\n\n        oldPriceRrp()\n        {\n            return this.$translate('Ceres::Template.liveShoppingRrp', {'price': '<del>' + this.prices.rrp.unitPrice.formatted + '</del>'})\n        }\n    },\n\n    created()\n    {\n        this.initializeDataAndTimer();\n    },\n\n    methods:\n    {\n        initializeDataAndTimer()\n        {\n            const momentNow = dayjs();\n\n            this.momentBegin = dayjs.unix(this.liveShoppingData.liveShopping.fromTime);\n            this.momentEnd = dayjs.unix(this.liveShoppingData.liveShopping.toTime);\n            this.hasStarted = this.momentBegin.valueOf() < momentNow.valueOf();\n            this.hasClosed = this.momentEnd.valueOf() < momentNow.valueOf();\n\n            this.setQuantitySoldPercentage();\n\n            if (this.hasStarted && !this.hasClosed)\n            {\n                this.setItemPriceRebatePercentage();\n            }\n\n            clearInterval(this.currentInterval);\n\n            this.calculations();\n            this.currentInterval = setInterval(() =>\n            {\n                this.calculations();\n            }, 1000);\n        },\n\n        setQuantitySoldPercentage()\n        {\n            const data            = this.liveShoppingData.liveShopping;\n            const percentage      = 100 - data.quantitySold / data.quantityMax * 100;\n\n            this.itemQuantityRemaining = data.quantityMax - data.quantitySold;\n            this.quantitySoldPercentage = percentage.toFixed(App.config.item.storeSpecial);\n        },\n\n        setItemPriceRebatePercentage()\n        {\n            const specialOfferPrice = this.prices.price.price.value;\n            const defaultPrice      = this.prices.rrp && this.prices.rrp.price.value || 0;\n\n            if (defaultPrice === 0)\n            {\n                this.itemPriceRebatePercentage = 0;\n            }\n            else\n            {\n                let percentage          = 100 - specialOfferPrice / defaultPrice * 100;\n\n                percentage = percentage.toFixed(App.config.item.storeSpecial);\n                percentage = percentage.replace(\".\", App.decimalSeparator);\n\n                this.itemPriceRebatePercentage = percentage;\n            }\n\n        },\n\n        calculations()\n        {\n            const momentNow = dayjs();\n            let fullSeconds = 0;\n            let remainSeconds = 0;\n\n            fullSeconds = this.momentEnd.diff(this.momentBegin, \"second\");\n            if (this.hasStarted)\n            {\n                remainSeconds = this.momentEnd.diff(momentNow, \"second\");\n            }\n            else\n            {\n                remainSeconds = this.momentBegin.diff(momentNow, \"second\");\n            }\n\n            this.timePercentage = (remainSeconds / fullSeconds * 100).toFixed(App.config.item.storeSpecial);\n            this.duration = this.getDuration(remainSeconds);\n\n            const hasToStart = !this.hasStarted && this.momentBegin < momentNow;\n            const hasToClose = !this.hasClosed && this.momentEnd < momentNow;\n\n            if (hasToStart || hasToClose)\n            {\n                clearInterval(this.currentInterval);\n\n                this.$emit(\"reload-offer\");\n            }\n        },\n\n        getDuration(seconds)\n        {\n            const days = Math.floor(seconds / (60 * 60 * 24));\n\n            seconds = seconds - (days * 60 * 60 * 24);\n\n            const hours = Math.floor(seconds / (60 * 60));\n\n            seconds = seconds - (hours * 60 * 60);\n\n            const minutes = Math.floor(seconds / 60);\n\n            seconds = seconds - (minutes * 60);\n\n            return {\n                days: days,\n                hours: hours,\n                minutes: minutes,\n                seconds: seconds\n            };\n        }\n    },\n\n    watch:\n    {\n        liveShoppingData()\n        {\n            this.initializeDataAndTimer();\n        }\n    }\n}\n</script>\n","<template>\n    <div>\n        <category-item\n                v-if=\"!!currentOffer\"\n                :item-data=\"currentOffer.item\"\n                :decimal-count=\"$ceres.config.item.storeSpecial\"\n                image-url-accessor=\"urlMiddle\"\n                :padding-classes=\"paddingClasses\"\n                :padding-inline-styles=\"paddingInlineStyles\">\n            <template #store-special>\n                <item-store-special \n                                    :store-special=\"storeSpecial\"\n                                    :recommended-retail-price=\"prices.rrp\"\n                                    :variation-retail-price=\"prices.price\"\n                                    :decimal-count=\"$ceres.config.item.storeSpecial \">\n                </item-store-special>\n            </template>\n            <template #item-image>\n                    <a v-if=\"!!displaySettings.customImagePath\" :href=\"currentOffer.item | itemURL\">\n                        <lazy-img   :image-url=\"displaySettings.customImagePath\"\n                                    :alt=\"currentOffer.item | itemName\"\n                                    :title=\"currentOffer.item | itemName\">\n                        </lazy-img>\n                    </a>\n            </template>\n            <template #item-details v-if=\"!!currentOffer \">\n                <live-shopping-details :live-shopping-data=\"currentOffer\"\n                                       @reload-offer=\"reloadOffer()\"\n                                       :display-settings=\"displaySettings\"\n                                       :prices=\"prices\"\n                                       :is-active-by-stock=\"isActiveByStock\"\n                                       :show-net-prices=\"showNetPrices\">\n                    <template #after-item-name>\n                        <div class=\"live-shopping-add-to-basket\">\n                            <add-to-basket\n                                    :variation-id=\"currentOffer.item.variation.id\"\n                                    :is-salable=\"!!currentOffer.item.filter && currentOffer.item.filter.isSalable\"\n                                    :has-children=\"!!currentOffer.item.filter && currentOffer.item.filter.hasActiveChildren\"\n                                    :interval-quantity=\"currentOffer.item.variation.intervalOrderQuantity || 1\"\n                                    :minimum-quantity=\"currentOffer.item.variation.minimumOrderQuantity\"\n                                    :maximum-quantity=\"!!currentOffer.item.variation.maximumOrderQuantity && currentOffer.item.variation.maximumOrderQuantity > 0 ? currentOffer.item.variation.maximumOrderQuantity : null\"\n                                    :order-properties=\"currentOffer.item.properties.filter(function(prop) { return prop.property.isOderProperty })\"\n                                    :has-order-properties=\"currentOffer.item.hasOrderProperties\"\n                                    :use-large-scale=\"false\"\n                                    :show-quantity=\"false\"\n                                    :item-url=\"currentOffer.item | itemURL\"\n                                    :item-type=\"currentOffer.item.item.itemType\">\n                            </add-to-basket>\n                        </div>\n                    </template>\n                </live-shopping-details>\n            </template>\n        </category-item>\n        <div v-else>\n            <slot></slot>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\nimport { isNullOrUndefined } from \"../../helper/utils\";\n\nimport LiveShoppingDetails from \"./LiveShoppingDetails.vue\";\nimport ItemStoreSpecial from \"../itemList/ItemStoreSpecial.vue\";\n\nconst TimeEnum = Object.freeze({ past: 1, now: 2, future: 3 });\n\nexport default {\n\n    components:\n    {\n        LiveShoppingDetails,\n        ItemStoreSpecial\n    },\n\n    props: {\n        liveShoppingId:\n        {\n            type: Number,\n            required: true,\n            validator: value =>\n            {\n                return value % 1 === 0 && value >= 1 && value <= 10;\n            }\n        },\n        displaySettings:\n        {\n            type: Object\n        },\n        paddingClasses:\n        {\n            type: String,\n            default: null\n        },\n        paddingInlineStyles:\n        {\n            type: String,\n            default: null\n        },\n        sorting:\n        {\n            type: String,\n            default: null\n        },\n        showNetPrices:\n        {\n            type: Boolean\n        }\n    },\n\n    computed:\n    {\n        currentOffer()\n        {\n            return this.$store.state.liveShopping.liveShoppingOffers[this._uid];\n        },\n\n        isActive()\n        {\n            return this.isActiveByTime && this.isActiveByStock;\n        },\n\n        isActiveByTime()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                const begin = parseInt(this.currentOffer.liveShopping.fromTime) * 1000;\n                const end = parseInt(this.currentOffer.liveShopping.toTime) * 1000;\n                const now = Date.now();\n\n                return begin < now && now < end;\n            }\n\n            return false;\n        },\n\n        isActiveByStock()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                const liveShopping = this.currentOffer.liveShopping;\n\n                return liveShopping.quantitySold < liveShopping.quantityMax;\n            }\n\n            return false;\n        },\n\n        storeSpecial()\n        {\n            if (!isNullOrUndefined(this.currentOffer))\n            {\n                if (this.isActive)\n                {\n                    return { id: 1 };\n                }\n\n                const offerTime = this.whenIsCurrentOffer();\n                let name = \"\";\n\n                if (offerTime === TimeEnum.past)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingOfferClosed\");\n                }\n                else if (offerTime === TimeEnum.future)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingNextOffer\");\n                }\n                else if (offerTime === TimeEnum.now)\n                {\n                    name = this.$translate(\"Ceres::Template.liveShoppingOfferSoldOut\");\n                }\n\n                return { id: -1, names: { name } };\n            }\n\n            return null;\n        },\n\n        prices()\n        {\n            const itemPrices = this.currentOffer.item.prices;\n            const prices = {\n                price: itemPrices.default,\n                rrp: itemPrices.rrp,\n                isRrpDefaultPrice: false\n            };\n\n            if (!isNullOrUndefined(itemPrices.specialOffer))\n            {\n                prices.price = itemPrices.specialOffer;\n                prices.rrp = itemPrices.default || itemPrices.rrp;\n                prices.isRrpDefaultPrice = !!itemPrices.default;\n            }\n\n            return prices;\n        }\n    },\n\n    mounted()\n    {\n        this.reloadOffer();\n    },\n\n    methods:\n    {\n        whenIsCurrentOffer()\n        {\n            const begin = parseInt(this.currentOffer.liveShopping.fromTime) 